// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FieldRecord) predicate.FieldRecord {
	return predicate.FieldRecord(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FieldRecord) predicate.FieldRecord {
	return predicate.FieldRecord(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FieldRecord) predicate.FieldRecord {
	return predicate.FieldRecord(sql.NotPredicates(p))
}
